import { Component, computed, inject, resource } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterLink } from '@angular/router';
import { firstValueFrom } from 'rxjs';
import { SolicitudService } from '../../../shared/services/solicitud.service';
import { AuthService } from '../../../services/auth.service';
import { statusToClass, semaforoBadgeClass } from '../../../shared/models/solicitud-status.util';

@Component({
  selector: 'app-seguimiento-municipal-list',
  imports: [CommonModule, RouterLink],
  templateUrl: './seguimiento-municipal-list.component.html',
})
export class SeguimientoMunicipalListComponent {
  private readonly solicitudService = inject(SolicitudService);
  protected readonly authService = inject(AuthService);
  protected readonly statusToClass = statusToClass;
  protected readonly semaforoBadgeClass = semaforoBadgeClass;

  private readonly solicitudesResource = resource({
    loader: () => firstValueFrom(this.solicitudService.getSolicitudes({ page: 1, perPage: 100 })),
  });

  readonly solicitudes = computed(() => this.solicitudesResource.value()?.data ?? []);
  readonly loading = computed(() => this.solicitudesResource.isLoading());
  readonly hasError = computed(() => this.solicitudesResource.error() !== undefined && !this.solicitudesResource.isLoading());
}
